def build_stepper(step_status: dict[int, str]) -> list[dict[str, Any]]:
    return [
        {
            "num": num,
            "title": meta["title"],
            "icon": ICONS[STEP_ICONS[num]],
            "status": step_status.get(num, "info"),
        }
        for num, meta in STEP_META.items()
    ]


